/* ---------- Wie lernt eine KI? ---------- */
function gKiLern(T) {
  gs.className = 'gs g-xs g-kil';
  const D = 'kil', g = G(), KP = [['cat', 'dog', 'Cat', 'Dog', 'a cat', 'a dog', '/grundschulmax/sp/kil/catc.webp', '/grundschulmax/sp/kil/dogc.webp'], ['apple', 'banana', 'Apple', 'Banana', 'an apple', 'a banana', '/grundschulmax/sp/eshop/apple.webp', '/grundschulmax/sp/eshop/banana.webp'], ['teddy', 'bear', 'Teddy', 'Real bear', 'a teddy', 'a real bear', '/grundschulmax/sp/eshop/teddy.webp', '/grundschulmax/sp/eshop/bear.webp']][gVar('kil', 3)];
  const SCH = [['t', 't', 't', 't', 'x', 'x', 'x'], ['t', 't', 't', 't', 'x', 'x', 'x'], ['t', 't', 't', 'x', 'x', 'q', 'q'], ['t', 't', 't', 'x', 'x', 'q', 'q']][g], N = SCH.length;
  const QZ = shuf([['How does an AI learn?', ['From lots and lots of examples', 'It knows everything from the start', 'Through magic spells']], ['Can an AI make mistakes?', ['Yes, so it\'s better to check', 'No, never', 'Only on weekends']], ['Who shows an AI what\'s right?', ['People who give it examples', 'Nobody, it just knows', 'The animals themselves']]].concat(g >= 3 ? [['An AI has only seen pictures of dogs. What happens with a cat?', ['It might think the cat is a dog', 'It recognizes the cat right away', 'It breaks']]] : []));
  let learned = 0, qi = 0;
  gs.innerHTML = `<div class="gsky" style="--bg:url(${xImg(D, 'bg')})"></div><img class="kgear" id="kgr" src="${xImg(D, 'gear')}" alt=""><div class="kcube" id="kcb"><img src="${xImg(D, 'cube')}" alt=""><b id="kcn">0</b></div><img class="kbulb" id="kbl" src="${xImg(D, 'bulb')}" alt=""><img class="kbot" id="kbt" src="${xImg(D, 'rthink')}" alt=""><div class="kcard" id="kcd"></div><div class="xq" id="xq"></div><div class="xopts" id="xo"></div>`;
  const card = (k, guess) => { $('#kcd').innerHTML = k ? `<img src="${k === 'cat' ? KP[6] : KP[7]}" alt="">${guess ? `<span class="kguess">${guess}</span>` : ''}` : ''; if (k) restart($('#kcd'), 'pop'); };
  const next = xRound(T, { N, done: 'The AI learned a lot!', doneT: ['An AI learns from examples.', 'An AI learns with examples.', 'Learn, test, improve.', 'That\'s how real AIs learn.'], okMs: 1500,
    onShow: () => { $('#kbt').src = xImg(D, 'rthink'); },
    make: (r) => { const t = SCH[r];
      if (t === 't') { const k = Math.random() < .5 ? 'cat' : 'dog'; card(k); return { html: `<b>Teach the AI: what's in the picture?</b><small>The AI learns from your examples.</small>`, o: [{ k: 'cat', label: KP[2] }, { k: 'dog', label: KP[3] }], a: k, okT: `The AI remembers: that's ${k === 'cat' ? KP[4] : KP[5]}!`, noT: 'Oops! With wrong examples, an AI learns wrong things.', _t: 't' }; }
      if (t === 'x') { const k = Math.random() < .5 ? 'cat' : 'dog', right0 = Math.random() < .5 + learned * .08, gu = right0 ? k : k === 'cat' ? 'dog' : 'cat'; card(k, `I think: ${gu === 'cat' ? KP[2] : KP[3]}!`); return { html: `<b>Test! Did the AI guess right?</b><small>Look at the picture closely.</small>`, o: [{ k: 'y', label: 'True' }, { k: 'n', label: 'False' }], a: right0 ? 'y' : 'n', okT: right0 ? 'The AI learned it right!' : 'Good catch! Even an AI makes mistakes. That\'s why we check.', noT: right0 ? 'Actually, the AI was right.' : 'The AI got it wrong! An AI can make mistakes.', _t: 'x' }; }
      card(''); const q = QZ[qi++ % QZ.length]; return { html: `<b>${q[0]}</b>`, o: tOpts(q[1]), a: '0', okT: 'Exactly!', noT: `The right answer: ${q[1][0]}.`, _t: 'q' }; },
    onPick: (ok, cur) => { const b = $('#kbt'); b.src = xImg(D, ok ? 'rhappy' : 'rques'); restart(b, ok ? 'yay' : 'shake');
      if (ok && cur._t === 't') { learned++; $('#kcn').textContent = learned; const c = $('#kcd img'); if (c) { const a = c.getBoundingClientRect(), z = $('#kcb').getBoundingClientRect(); c.animate([{ transform: 'none' }, { transform: `translate(${z.left - a.left + z.width / 2 - a.width / 2}px,${z.top - a.top + z.height / 2 - a.height / 2}px) scale(.2)`, opacity: .2 }], { duration: 650, easing: 'cubic-bezier(.5,0,.6,1)', fill: 'forwards' }); } setTimeout(() => { restart($('#kcb'), 'gulp'); restart($('#kgr'), 'spin'); restart($('#kbl'), 'glow'); }, 620); }
      if (ok && cur._t !== 't') restart($('#kbl'), 'glow'); } });
  progress(N); say('Help the AI learn! Show it examples and then test it.', '');
  startOverlay('Start training', `${N} rounds · how an AI learns`, next);
  return () => {};
}

