    $$('.fxsp[data-sp]', v).forEach((b) => (b.onclick = () => { const [d, j] = b.dataset.sp.split('-').map(Number), gi = b.dataset.gi, G0 = /^fx:/.test(gi) ? gi : +gi; const i0 = FS_PLAN.findIndex((x, k) => { const s = fsSpAfter(k); return s && s.d === d && s.j === j; }); const s0 = i0 >= 0 ? fsSpAfter(i0) : { d, j, gi: G0 }; selSp = s0; userSel = true; draw(); if (innerWidth < 900) { const dd = $('.fxdet', v); dd && dd.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }));
    $$('[data-play]', v).forEach((b) => (b.onclick = () => fsGame(+b.dataset.play, () => draw())));
    $$('.fxu[data-i]', v).forEach((b) => (b.onclick = () => { sel = +b.dataset.i; selSp = null; userSel = true; if (typeof LV_SD !== 'undefined') LV_SD = 0; draw(); if (innerWidth < 900) { const d = $('.fxdet', v); d && d.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }));
