    if (pass) { fsMark(g, C.fi); const ok = fsOk(); if (!ok[g + 1]) { GT.t('License passed', fsCur().n + ' · ' + acc + ' %'); ok[g + 1] = Date.now(); try { localStorage.setItem(fsCur().ok, JSON.stringify(ok)); } catch (e) {} if (typeof kPush === 'function') try { kPush(); } catch (e) {} } }
