/* ---------- 2. Rollentausch: Das Kind prüft die Eltern ---------- */
const FAM_RT = [
  { app: 'WhatsApp', from: '+1 (305) 418-2093', ico: 'chat', msg: 'Hi Mom, this is my new number. My phone broke. Can you send me $480 today? It’s urgent, I’ll explain later ❤️', fake: 1,
    why: ['An unknown number claiming to be family.', 'It’s about money right away.', 'Time pressure: “today”, “urgent”.'], tip: 'Always call back on the old number you know.', ask: 'What would you do if a message like this arrived?' },
  { app: 'Call', from: 'Unknown', ico: 'phone', msg: '(crying, in the daughter’s voice) “Mom, I had an accident! I need money for the police right now. Please don’t tell Dad!”', fake: 1,
    why: ['AI can copy voices.', 'Panic, money and “don’t tell anyone”: three warning signs at once.', 'Real police never ask for money over the phone.'], tip: 'Ask for the family code word. If it doesn’t come: hang up and call yourself.', ask: 'Does everyone in the family know our code word?' },
  { app: 'SMS', from: 'USPS-Info', ico: 'chat', msg: 'Your package could not be delivered. Please pay the $1.99 redelivery fee here: usps-redelivery-help.info', fake: 1,
    why: ['The address is not the real USPS website.', 'The small amount is bait: what they steal is your card details.', 'Real delivery services don’t send links like this by text.'], tip: 'Never tap the link. Check deliveries directly in the real app.', ask: 'Have you ever received a text like this?' },
  { app: 'Game chat', from: 'xX_GiftBot_Xx', ico: 'chat', msg: 'FREE 10,000 coins for your game! 🎁 Today only: log in here with your account: free-coins-event.net', fake: 1,
    why: ['Too good to be true.', 'Logging in on a strange site: that’s how accounts get stolen.', '“Today only” is meant to stop you from thinking.'], tip: 'Never type a password on a site from a chat.', ask: 'Who would you tell if this happened to you?' },
  { app: 'School app', from: 'Mrs. Berger, homeroom teacher', ico: 'chat', msg: 'Dear parents, tomorrow is our field trip. Please send your child with a rain jacket and a snack. Best, A. Berger', fake: 0,
    why: ['Comes through the official school app you know.', 'No link, no money, no password.', 'No pressure and no secret.'], tip: 'Not everything is a trap. Real messages don’t want anything from you.', ask: 'How can you quickly tell that something is real?' },
  { app: 'Instagram', from: 'lea.2014_official', ico: 'chat', msg: 'Hey 😊 you look so cute in your pics! I’m 12 too. Send me a photo just for me, but don’t tell anyone, ok?', fake: 1,
    why: ['Lots of compliments from a stranger.', '“Don’t tell anyone” is always a red flag.', 'Strangers asking for photos: that can lead to blackmail.'], tip: 'Don’t reply, block, and show Mom or Dad right away.', ask: 'What should your kid do so they never have to be afraid of getting in trouble?' },
];
function famRollentausch(nm, after) {
  const kid = nm || 'Your kid', m = famShell('fm-rt', 'Role swap'); let i = -1, score = 0, picked = null; const N = FAM_RT.length + 2;
  const close = () => { m.remove(); document.body.classList.remove('fxfmon'); if (after) after(); };
  $('.fxfmx', m).onclick = close;
  const draw = () => {
    famDots(m, i + 1, N);
    if (i < 0) { famPaint(m, `<div class="fxfmhero rt"><div class="fxfmswap"><span class="k"><small>Today’s examiner</small><b>${esc(kid)}</b></span><i>${FAM_I.swap}</i><span class="p"><small>Today’s test-takers</small><b>Mom and Dad</b></span></div></div>
      <span class="fxeye">Family time · about 15 minutes</span><h2>Role swap: ${esc(kid)} tests you</h2>
      <p class="fxfml"><b>${esc(kid)}:</b> Now you’re the expert. Read each case out loud to Mom and Dad. They guess: real or trap? Then you explain how to spot it.</p>
      <p class="fxfml"><b>For parents:</b> Explaining something is how you truly understand it. And you get to see for yourself what your kid has learned. Feel free to get fooled once in a while.</p>
      <div class="fxfmwhy">${FAM_I.heart}<div><b>What this is really about</b><p>${FAM_WHY}</p></div></div>
      <div class="fxfmn"><span></span><button type="button" class="fxbtn fxfmgo">Start the role swap ${FX.arrow}</button></div>`); }
    else if (i < FAM_RT.length) {
      const c = FAM_RT[i], res = picked !== null;
      const right = res && (picked === c.fake);
      famPaint(m, `<span class="fxeye">Case ${i + 1} of ${FAM_RT.length} · ${esc(kid)} reads aloud</span>
        <div class="fxfmmsg"><div class="fxfmmh"><span>${FAM_I[c.ico]}</span><div><small>${esc(c.app)}</small><b>${esc(c.from)}</b></div></div><p>${esc(c.msg)}</p></div>
        ${res ? `<div class="fxfmres ${right ? 'ok' : 'no'}"><b>${right ? 'Spotted it!' : (c.fake ? 'Got you! That was a trap.' : 'Close, but that one was real.')}</b><span>${c.fake ? 'Trap' : 'Real'}</span></div>
          <div class="fxfmexp"><small>${esc(kid)} explains:</small><ul>${c.why.map((w) => `<li>${esc(w)}</li>`).join('')}</ul><p><b>What to do:</b> ${esc(c.tip)}</p></div>
          <div class="fxfmask">${FAM_I.chat}<div><small>Talk about it for a minute</small><b>${esc(c.ask)}</b></div></div>
          <div class="fxfmn"><span></span><button type="button" class="fxbtn fxfmgo">${i < FAM_RT.length - 1 ? 'Next case' : 'See the result'} ${FX.arrow}</button></div>`
          : `<p class="fxfmq">Mom and Dad, what do you think?</p><div class="fxfmpick"><button type="button" data-p="0"><i>${FAM_I.ok}</i>Real</button><button type="button" data-p="1"><i>${FAM_I.x}</i>Trap</button></div>`}`);
      $$('.fxfmpick [data-p]', m).forEach((b) => (b.onclick = () => { picked = +b.dataset.p; if (picked === c.fake) { score++; try { sfx.ok(); } catch (e) {} } else { try { sfx.bad && sfx.bad(); } catch (e) {} } draw(); }));
    } else {
      const all = score === FAM_RT.length;
      famSet('rt', Date.now()); famSet('rtS', score); try { GT.t('Familienzeit', 'Role swap ' + score + ' von ' + FAM_RT.length); sfx.win(); confetti(60); } catch (e) {}
      famPaint(m, `<div class="fxfmend"><span class="fxfmendi">${FAM_I.swap}</span><span class="fxeye">Role swap complete</span><h2>Mom and Dad: ${score} of ${FAM_RT.length} spotted</h2>
        <p class="fxfml">${all ? 'Awesome! And ' + esc(kid) + ' explained every case.' : esc(kid) + ' was the expert today. That’s exactly how it should be.'} Now your family has a shared language for these topics.</p>
        <div class="fxfmtalk"><b>Three questions for tonight</b><ol><li>What was the meanest trick for you?</li><li>Who would you tell right away if something online felt off?</li><li>What do we promise each other as a family? (For example: whoever speaks up never gets in trouble.)</li></ol></div>
        <button type="button" class="fxbtn fxfmok">Back to the course ${FX.arrow}</button></div>`); famDots(m, N, N); $('.fxfmok', m).onclick = close; return;
    }
    const go = $('.fxfmgo', m); if (go) go.onclick = () => { i++; picked = null; draw(); };
  };
  draw();
}

/* ---------- 0. Notfall-Pass: das Familien-Versprechen ---------- */
function famNotfall(after) {
  const m = famShell('fm-np', 'Emergency pass'); const done0 = typeof fsCh === 'function' && !!fsCh()[1];
  const close = () => { m.remove(); document.body.classList.remove('fxfmon'); if (after) after(); };
  $('.fxfmx', m).onclick = close; $('.fxfmd', m).innerHTML = '';
  const body = (done) => `<div class="fxfmhero np"><span class="fxfmnpi">${FAM_I.shield}</span><p>“If you come to us, you get help first. No trouble, no phone ban.”</p><small>The promise that makes everything else possible</small></div>
    <span class="fxeye">Family time · about 5 minutes</span><h2>Your emergency pass</h2>
    <p class="fxfml">The biggest risk online is often not the trap itself, but the silence afterwards. Many kids don’t tell anyone because they’re afraid of losing their phone. The emergency pass takes away exactly that fear.</p>
    <div class="fxfmnp"><div><small>On your kid’s pass</small><ol><li><b>Don’t reply, don’t click.</b></li><li><b>Take a screenshot.</b></li><li><b>Get a grown-up.</b></li></ol></div><div><small>Your family promise</small><ul><li>We won’t get mad when you show us something.</li><li>We won’t secretly delete anything, we solve it together.</li><li>Strangers who want secrets are never your fault.</li></ul></div></div>
    <a class="fxbtn fxfmbig" href="/notfall" target="_blank" rel="noopener">${FAM_I.print}Open emergency pass and poster ${FX.arrow}</a>
    <div class="fxfmprep"><b>How it works:</b><span>1. Open it and print both pages. 2. Read it out loud together and both sign it. 3. The poster goes in the kid’s room, the pass on the fridge or in the backpack.</span></div>
    <div class="fxfmwhy">${FAM_I.heart}<div><b>Why this is more than a checkbox</b><p>${FAM_WHY}</p></div></div>
    <div class="fxfmdone">${done ? `<span class="fxfmok2">${FAM_I.ok}Done! You have your emergency pass.</span>` : `<button type="button" class="fxbtn fxfmfin">${FX.check} Done! We signed it</button><small>Only tap once you’ve signed it together. Tonight is totally fine.</small>`}</div>`;
  famPaint(m, body(done0));
  const op = $('.fxfmbig', m); if (op) op.onclick = () => { try { GT.t('Familienzeit', 'Notfall-Pass geöffnet'); } catch (e) {} };
  const fi = $('.fxfmfin', m); if (fi) fi.onclick = () => { if (typeof fsChSet === 'function') fsChSet(1); try { GT.t('Familienzeit', 'Notfall-Pass geschafft'); sfx.win(); confetti(50); } catch (e) {}
    famPaint(m, `<div class="fxfmend"><span class="fxfmendi">${FAM_I.shield}</span><span class="fxeye">Done</span><h2>Your emergency pass is valid from today</h2><p class="fxfml">From now on your kid knows: whatever happens online, they can come to you. Remind each other every now and then, for example at dinner.</p><button type="button" class="fxbtn fxfmok">Back to the course ${FX.arrow}</button></div>`); $('.fxfmok', m).onclick = close; };
}

/* Testbereich für Besucher (/app#test): sieht aus wie der echte Führerschein. Frei sind nur die Gratis-Testlektion (die stärksten Szenen
   aus Internet, Fremden und KI) und einmal der Simulator des Tages. Alles andere ist sichtbar, aber gesperrt und öffnet das Freischalten-Fenster.
   Speicher nur unter mi-demo (nie in den echten Kurs-Schlüsseln, damit ein späterer Kauf sauber startet). */
let FSD = false;
