    const fitLbl = () => { if (!sc.isConnected) return; $$('.glb, .ml > span, .fsh > span, .qpl > span', sc).forEach((l) => { l.style.removeProperty('font-size'); const cs = getComputedStyle(l); let fs = parseFloat(cs.fontSize) || 16; const lhf = cs.lineHeight === 'normal' ? 1.2 : (parseFloat(cs.lineHeight) || fs * 1.2) / fs, pad = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0) + (parseFloat(cs.borderTopWidth) || 0) + (parseFloat(cs.borderBottomWidth) || 0); let k = 0; while (k++ < 14 && fs > 10 && l.offsetHeight - pad > fs * lhf * 2 + 2) { fs -= 1; l.style.setProperty('font-size', fs + 'px', 'important'); } }); };
    requestAnimationFrame(fitLbl); setTimeout(fitLbl, 350);
