  const p = document.createElement('div'); p.className = 'praise' + (streak >= 3 ? ' big' : '');
  p.innerHTML = `<b>${streak >= 3 ? `${streak} in a row!` : pick(PRAISE)}</b>`;
  host.appendChild(p); setTimeout(() => p.remove(), 1500);
  if (streak >= 3) sfx.streak(); else sfx.ok();
  const fxl = les.classList.contains('fxl'); /* Führerschein: Sterne fliegen in den Fortschrittsbalken, der Balken leuchtet auf */
  const ex = $('.lesex', les), tgt = fxl ? $('.lesbar i', les) : $('.lespts', les); if (!ex || !tgt) return;
  const a = ex.getBoundingClientRect(), b0 = tgt.getBoundingClientRect(); if (!b0.width && !b0.height) return;
