    if (k === 'gull') return `<span class="am-bird am-gull" style="--y:${r(5, 14)}%;--d:${r(20, 26)}s;--dl:-${r(0, 14)}s"><img src="${AMBI('gull')}" alt=""><img src="${AMBI('gull')}" alt=""></span>`;
    if (k === 'bfly') return `<span class="am-bfly" style="--x:${r(8, 80)}%;--y:${r(30, 60)}%;--d:${r(11, 15)}s"><img src="${AMBI('bfly')}" alt=""></span>`;
    if (k === 'dfly') return `<span class="am-bfly am-dfly" style="--x:${r(55, 85)}%;--y:${r(20, 40)}%;--d:${r(9, 12)}s"><img src="${AMBI('dfly')}" alt=""></span>`;
    if (k === 'shoot') return `<img class="am-shoot" src="${AMBI('shoot')}" style="--d:${r(7, 10)}s;--dl:-${r(0, 6)}s" alt="">`;
    if (k === 'palm') return `<img class="am-palm l" src="${AMBI('palm')}" alt=""><img class="am-palm r" src="${AMBI('palm')}" alt="">`;
    if (k === 'bubble') return [0, 1, 2].map((i) => `<img class="am-bub" src="${AMBI('bubble')}" style="--x:${r(10, 90)}%;--w:${r(2.5, 5)}%;--d:${r(7, 11)}s;--dl:-${r(0, 9)}s" alt="">`).join('');
    if (k === 'spots') return [24, 50, 76].map((x, i) => `<img class="am-spot" src="${AMBI('spot')}" style="--x:${x}%;--dl:-${i * 1.3}s" alt="">`).join('');
    if (k === 'spark') return [0, 1, 2, 3].map(() => `<img class="am-spark" src="${AMBI('spark')}" style="--x:${r(8, 92)}%;--y:${r(15, 70)}%;--d:${r(2.6, 4)}s;--dl:-${r(0, 3)}s" alt="">`).join('');
    if (k === 'ripple') return [0, 1].map(() => `<img class="am-rip" src="${AMBI('ripple')}" style="--x:${r(15, 85)}%;--y:${r(40, 70)}%;--d:${r(3.5, 5)}s;--dl:-${r(0, 4)}s" alt="">`).join('');
    return '';
