async function payMount() {
  const my = ++payTok, host = $('#spay'), err = $('#pyerr');
  try { if (payObj) { payObj.destroy(); payObj = null; } } catch (e) {}
  const body = { mode: 'checkout', plan: su.plan, email: su.email || K.mail, grade: su.grade, embedded: !!STRIPE_PK };
  let r = null; try { r = await fetch(ABO_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }).then((x) => x.json()); } catch (e) {}
  if (my !== payTok || !host || !host.isConnected) return;
  if (!r || !r.ok) { host.innerHTML = ''; err.textContent = (r && r.grund) || 'Checkout is unavailable right now. Please try again in a moment.'; return; }
  if (r.url) { host.innerHTML = `<button class="b3d c wide" id="n2">${I('lock')}Weiter: 7 Tage kostenlos starten</button>`; $('#n2').onclick = () => { location.href = r.url; }; return; }
  try {
    const S = (await loadStripe())(STRIPE_PK, { locale: 'de' });
    const make = S.createEmbeddedCheckoutPage ? S.createEmbeddedCheckoutPage.bind(S) : S.initEmbeddedCheckout.bind(S);
    const co = await make({ fetchClientSecret: async () => r.cs });
    if (my !== payTok || !host.isConnected) { co.destroy(); return; }
    host.innerHTML = ''; co.mount(host); payObj = co;
  } catch (e) { host.innerHTML = ''; err.textContent = 'Checkout couldn\'t load. Please reload the page.'; }
}
